export const COUNTRY_CODES=new Set(COUNTRIES.map(c=>c.code));
let promise;
export function flagImages(){return promise??=fetch("/assets/country-flags.json").then(r=>{if(!r.ok)throw Error("Flag images could not load.");return r.json();}).then(flags=>Object.fromEntries(Object.entries(flags).map(([code,svg])=>[code,"data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg.replace('<svg ','<svg width="256" height="192" '))])));}

// Rasterize SVGs before WebGL upload: some mobile drivers render SVG textures black.
const flagCanvases=new Map();
export async function flagCanvas(code){
 if(!COUNTRY_CODES.has(code))throw Error('Unknown country flag');
 if(!flagCanvases.has(code))flagCanvases.set(code,(async()=>{const data=await flagImages(),image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Flag picture failed to load'));image.src=data[code];});const canvas=document.createElement('canvas');canvas.width=256;canvas.height=192;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Flag canvas unavailable');ctx.drawImage(image,0,0,256,192);return canvas;})().catch(error=>{flagCanvases.delete(code);throw error;}));
 return flagCanvases.get(code);
}
